// Google Drive share link → file id. Accepts /file/d/<id>/…, open?id=<id>, uc?id=<id>.
const job = $input.item.json;
const m = String(job.mediaUrl || '').match(/\/d\/([\w-]{10,})|[?&]id=([\w-]{10,})/);
return { json: { ...job, driveFileId: m ? (m[1] || m[2]) : '' } };

// Keep the job fields, learn image vs video from the downloaded file, choose a stable public file name.
const job = $('Parse Drive link').item.json;
const bin = $input.item.binary?.data;
if (!bin) throw new Error('Aucun fichier téléchargé depuis Google Drive.');
const mime = (bin.mimeType || '').toLowerCase();
const isVideo = mime.startsWith('video/');
const isImage = mime.startsWith('image/');
if (!isVideo && !isImage) throw new Error(`Type de fichier non pris en charge : ${mime || 'inconnu'}`);
const ext = (bin.fileExtension || (bin.fileName || '').split('.').pop() || (isVideo ? 'mp4' : 'jpg')).toLowerCase();
const safeId = String(job.postId).replace(/[^\w-]/g, '');
return { json: { ...job, mimeType: mime, isVideo, fileName: `${safeId}.${ext}` }, binary: { data: bin } };
